<template>
  <Teleport to="body"><Transition name="home-popup-fade"><div v-if="open && popup" class="home-popup-backdrop" role="presentation" @click.self="close"><section ref="dialog" class="home-popup" role="dialog" aria-modal="true" :aria-labelledby="popup.title ? 'home-popup-title' : undefined" :aria-label="popup.title ? undefined : 'Promotion'" tabindex="-1"><button ref="closeButton" type="button" class="home-popup__close" aria-label="Close" @click="close">×</button><div v-if="popup.imageUrl && !imageFailed" class="home-popup__image-wrap"><img :src="popup.imageUrl" :alt="popup.imageAlt || ''" @error="imageFailed = true"></div><div class="home-popup__content"><h2 v-if="popup.title" id="home-popup-title">{{ popup.title }}</h2><p v-if="popup.description">{{ popup.description }}</p><button v-if="popup.buttonText && popup.buttonUrl" type="button" class="home-popup__button" @click="clickButton">{{ popup.buttonText }}</button></div></section></div></Transition></Teleport>
</template>
<script setup lang="ts">
import { nextTick, onBeforeUnmount, ref, watch } from 'vue'
import type { HomePopup } from '~/composables/useHomePromotions'
const props = defineProps<{ popup?: HomePopup | null; open: boolean }>(); const emit = defineEmits<{ close: [] }>(); const { go, sendEvent } = useHomePromotions(); const dialog = ref<HTMLElement | null>(null); const closeButton = ref<HTMLButtonElement | null>(null); const imageFailed = ref(false); let previousOverflow = ''; let previousPosition = ''; let previousTop = ''; let previousWidth = ''; let previousScrollY = 0; let previousActive: HTMLElement | null = null
const close = () => emit('close'); const clickButton = async () => { if (props.popup) { await sendEvent('POPUP', props.popup, 'CLICK'); await go(props.popup.buttonUrl); close() } }
const onKeydown = (event: KeyboardEvent) => { if (event.key === 'Escape') close(); if (event.key === 'Tab' && dialog.value) { const focusable = dialog.value.querySelectorAll<HTMLElement>('button,[href]'); if (!focusable.length) return; const first = focusable[0]!; const last = focusable[focusable.length - 1]!; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() } } }
watch(() => props.open, async value => { if (!import.meta.client) return; if (value) { previousActive = document.activeElement as HTMLElement; previousScrollY = window.scrollY; previousOverflow = document.body.style.overflow; previousPosition = document.body.style.position; previousTop = document.body.style.top; previousWidth = document.body.style.width; document.body.style.overflow = 'hidden'; document.body.style.position = 'fixed'; document.body.style.top = `-${previousScrollY}px`; document.body.style.width = '100%'; document.addEventListener('keydown', onKeydown); await nextTick(); closeButton.value?.focus() } else { document.body.style.overflow = previousOverflow; document.body.style.position = previousPosition; document.body.style.top = previousTop; document.body.style.width = previousWidth; window.scrollTo(0, previousScrollY); document.removeEventListener('keydown', onKeydown); previousActive?.focus(); imageFailed.value = false } }, { immediate: true })
onBeforeUnmount(() => { document.body.style.overflow = previousOverflow; document.body.style.position = previousPosition; document.body.style.top = previousTop; document.body.style.width = previousWidth; document.removeEventListener('keydown', onKeydown) })
</script>
<style scoped>
.home-popup-backdrop{position:fixed;inset:0;z-index:1200;background:rgba(16,35,31,.56);display:grid;place-items:center;padding:20px}.home-popup{position:relative;width:min(550px,100%);max-height:calc(100vh - 40px);overflow:auto;background:#fff;border-radius:4px;box-shadow:0 18px 60px rgba(0,0,0,.22)}.home-popup__close{position:absolute;right:12px;top:10px;border:0;background:rgba(255,255,255,.85);border-radius:50%;width:32px;height:32px;font-size:25px;line-height:1;color:#17352f;cursor:pointer;z-index:1}.home-popup__image-wrap{width:100%;aspect-ratio:550/300;background:#eee}.home-popup__image-wrap img{width:100%;height:100%;object-fit:cover;display:block}.home-popup__content{text-align:center;padding:34px 42px 38px}.home-popup__content h2{margin:0 0 12px;color:#17352f;font-size:28px;line-height:1.2}.home-popup__content p{margin:0 auto 24px;color:#53645e;font-size:15px;line-height:1.65;max-width:430px}.home-popup__button{min-width:180px;padding:12px 22px;border:0;border-radius:2px;background:#105446;color:#fff;font-size:14px;cursor:pointer}.home-popup-fade-enter-active,.home-popup-fade-leave-active{transition:opacity .2s}.home-popup-fade-enter-active .home-popup,.home-popup-fade-leave-active .home-popup{transition:transform .2s ease}.home-popup-fade-enter-from,.home-popup-fade-leave-to{opacity:0}.home-popup-fade-enter-from .home-popup,.home-popup-fade-leave-to .home-popup{transform:scale(.97)}
</style>
